124	/// </summary>
125	/// <remarks>
126	/// 2026-11-09, FR-MCP-BUILD-001; TR-MCP-NUKE-019 AC-7; R15-F1: added as the real target boundary after the scripted
127	/// discovery contract. Discovery executes no test case. A project that Compile did not build may build on its first
128	/// discovery; every later discovery uses --no-build and --no-restore.
129	/// </remarks>
130	internal sealed class DotNetListTestDiscoverySource(
131	    string configuration,
132	    Func<string, bool>? buildOnFirstDiscovery = null) : ITestCaseDiscoverySource
133	{
134	    private readonly HashSet<string> builtByDiscovery = new(StringComparer.Ordinal);
135	
136	    /// <inheritdoc />
137	    public IReadOnlyList<string> Discover(string projectPath, string? filter)
138	    {
139	        ArgumentException.ThrowIfNullOrWhiteSpace(projectPath);
140	        var fullPath = Path.GetFullPath(projectPath);
141	        var mustBuild = buildOnFirstDiscovery?.Invoke(fullPath) == true && !builtByDiscovery.Contains(fullPath);
142	        var arguments = $"test \"{fullPath.Replace("\"", "\\\"")}\" --configuration \"{configuration}\" --list-tests --verbosity minimal";
143	        if (!mustBuild)
144	            arguments += " --no-build --no-restore";
145	        if (!string.IsNullOrWhiteSpace(filter))
146	            arguments += $" --filter \"{filter.Replace("\"", "\\\"")}\"";
147	
148	        var process = ProcessTasks.StartProcess("dotnet", arguments, logOutput: false, logInvocation: true);
149	        process.WaitForExit();
150	        process.AssertZeroExitCode();
151	        if (mustBuild)
152	            builtByDiscovery.Add(fullPath);
153	        return Parse(process.Output.Select(output => output.Text).ToArray());
154	    }
155	
156	    /// <summary>Parses the indented case identities after the VSTest list header.</summary>
157	    /// <param name="lines">The complete process output.</param>
158	    /// <returns>The discovered case identities; empty when the filter selects none.</returns>
159	    /// <exception cref="InvalidOperationException">The successful process output has no list header.</exception>
160	    internal static IReadOnlyList<string> Parse(IReadOnlyList<string> lines)
161	    {
162	        ArgumentNullException.ThrowIfNull(lines);
163	        var header = -1;
164	        for (var index = 0; index < lines.Count; index++)
165	        {
166	            if (string.Equals(lines[index].Trim(), "The following Tests are available:", StringComparison.Ordinal))
167	            {
168	                header = index;
169	                break;
170	            }
171	        }
172	        if (header < 0)
173	            throw new InvalidOperationException("dotnet list-tests output did not contain the test-list header.");
174	
175	        var cases = new List<string>();
176	        for (var index = header + 1; index < lines.Count; index++)
177	        {
178	            var raw = lines[index];
179	            var trimmed = raw.Trim();
180	            if (trimmed.Length == 0)
181	                continue;
182	            if (trimmed.StartsWith("No test matches the given testcase filter", StringComparison.Ordinal))
183	                return [];
184	            if (raw.Length == trimmed.Length)
185	                break;
186	            cases.Add(trimmed);
187	        }
188	        return cases;
189	    }
190	}
